.architecture-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 5rem;
  align-items: center;
}

.architecture-visual {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.5rem;
  display: flex;
  justify-content: center;
  align-items: center;
  box-shadow: 0 20px 45px -15px rgba(0, 0, 0, 0.6);
  position: relative;
  overflow: hidden;
}

.architecture-visual::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle at center, rgba(56, 189, 248, 0.04) 0%, transparent 70%);
  pointer-events: none;
}

.schema-svg {
  width: 100%;
  height: auto;
  max-width: 600px;
  background: transparent;
}

/* Base states for path drawing */
.svg-flow-path {
  stroke-dasharray: 8, 8;
  animation: svg-flow 25s linear infinite;
}

@keyframes svg-flow {
  from { stroke-dashoffset: 200; }
  to { stroke-dashoffset: 0; }
}

/* Blinking LEDs */
.svg-led-green {
  animation: led-blink-green 1s infinite alternate;
}
.svg-led-orange {
  animation: led-blink-orange 1.5s infinite alternate;
}

@keyframes led-blink-green {
  0% { fill: rgba(34, 197, 94, 0.4); filter: none; }
  100% { fill: #22c55e; filter: drop-shadow(0 0 4px rgba(34, 197, 94, 0.6)); }
}

@keyframes led-blink-orange {
  0% { fill: rgba(249, 115, 22, 0.4); filter: none; }
  100% { fill: #f97316; filter: drop-shadow(0 0 4px rgba(249, 115, 22, 0.6)); }
}

/* Pulsing waves */
.svg-signal-wave {
  stroke: var(--accent-cyan);
  stroke-linecap: round;
  transform-origin: bottom left;
  animation: wave-pulse 2s infinite ease-in-out;
}
.svg-signal-wave:nth-child(2) {
  animation-delay: 0.6s;
}
.svg-signal-wave:nth-child(3) {
  animation-delay: 1.2s;
}

